export const advanceUploadOriginal = (
    id: string,
    stage: string,
    advanceUploadOriginalBody: AdvanceUploadOriginalBody,
 options?: SecondParameter<typeof advanceHttp<AdvanceEvidenceDraft>>,) => {const formData = new FormData();
formData.append(`file`, advanceUploadOriginalBody.file);
formData.append(`kind`, advanceUploadOriginalBody.kind);
formData.append(`expectedRevision`, advanceUploadOriginalBody.expectedRevision.toString())

      return advanceHttp<AdvanceEvidenceDraft>(
      {url: `/v1/advance/campaigns/${id}/stages/${stage}/evidence/documents`, method: 'POST',
      headers: {'Content-Type': 'multipart/form-data', },
       data: formData
    },
      options);
    }

