export const advancePublishRedacted = (
    packageId: string,
    advancePublishRedactedBody: AdvancePublishRedactedBody,
 options?: SecondParameter<typeof advanceHttp<AdvancePublication>>,) => {const formData = new FormData();
advancePublishRedactedBody.files.forEach(value => formData.append(`files`, value));
formData.append(`summary`, advancePublishRedactedBody.summary);
formData.append(`redactionConfirmed`, advancePublishRedactedBody.redactionConfirmed);
formData.append(`originalDocumentIds`, advancePublishRedactedBody.originalDocumentIds);

      return advanceHttp<AdvancePublication>(
      {url: `/v1/advance/evidence-packages/${packageId}/redacted`, method: 'POST',
      headers: {'Content-Type': 'multipart/form-data', },
       data: formData
    },
      options);
    }

